unit_test_code:
dec=ns['count_calls'];
@dec
def f(x): return x+1
assert f(1)==2 and f(2)==3 and getattr(f,'calls')==2
return 'count_calls() passed cases'

f=ns['is_valid_bst']; T=ns.get('TreeNode')
if T is None:
    class T:
        def __init__(self,val,left=None,right=None): self.val=val; self.left=left; self.right=right
r=T(2,T(1),T(3)); bad=T(2,T(3),T(1)); assert f(r) is True and f(bad) is False
return 'is_valid_bst() passed cases'

f=ns['retry']; state={'n':0}
def flaky():
    state['n']+=1
    if state['n']<2: raise ValueError('x')
    return 7
assert f(flaky,3,0)==7
return 'retry() passed cases'
